t.script:
document.addEventListener('DOMContentLoaded', function () {
    var button = document.getElementById('validate_single');
    var resultsBody = document.getElementById('results_body');

    var addCell = function (row, text, cssClass, colSpan) {
        var cell = document.createElement('td');
        cell.textContent = text;
        if (cssClass) {
            cell.className = cssClass;
        }
        if (colSpan) {
            cell.colSpan = colSpan;
        }
        row.appendChild(cell);
    };

    var fillRow = function (row, email, status, cssClass, message) {
        row.replaceChildren();
        addCell(row, email);
        addCell(row, status, cssClass);
        addCell(row, message);
    };

    var validateEmail = function (email, validatorId) {
        return fetch('/email_validation/validate_ajax', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {email: email, validator_id: validatorId},
            }),
        }).then(function (response) {
            return response.json();
        }).then(function (data) {
            if (data.error) {
                throw new Error(data.error.message);
            }
            return data.result;
        });
    };

    button.addEventListener('click', function () {
        var emails = document.getElementById('emails').value
            .split('\n')
            .map(function (email) { return email.trim(); })
            .filter(function (email) { return email !== ''; });

        if (emails.length === 0) {
            alert('Enter at least one email address');
            return;
        }

        var validatorId = document.getElementById('validator_id').value;
        resultsBody.replaceChildren();
        document.getElementById('validation_results').style.display = '';

        var processEmails = function (index) {
            if (index >= emails.length) {
                return;
            }
            var email = emails[index];
            var row = document.createElement('tr');
            addCell(row, email);
            addCell(row, 'Checking...', '', 2);
            resultsBody.appendChild(row);

            validateEmail(email, validatorId).then(function (result) {
                if (result.error) {
                    fillRow(row, email, result.error, 'text-danger', '');
                } else if (result.state === 'valid') {
                    fillRow(row, email, 'Valid', 'text-success', result.message || '');
                } else if (result.state === 'invalid') {
                    fillRow(row, email, 'Invalid', 'text-danger', result.message || '');
                } else {
                    fillRow(row, email, 'Pending', 'text-warning', result.message || '');
                }
            }).catch(function () {
                fillRow(row, email, 'Error', 'text-danger', 'Failed to validate address');
            }).then(function () {
                processEmails(index + 1);
            });
        };

        processEmails(0);
    });
});
